import { z } from "zod";
import raw from "@/data/tour.json";
import { PERSONA_KEYS } from "@/lib/personas";

// Presenter tour (DEV_GUIDE §9.4). data/tour.json is generated by `npm run tour:generate` and may be edited;
// this schema is the contract for both the /tour page and /api/tour (which only performs these declared actions).

const Sku = z.string().regex(/^[A-Z0-9-]{3,40}$/);
const Target = z.discriminatedUnion("type", [
  z.object({ type: z.literal("product"), sku: Sku }),
  z.object({ type: z.literal("category"), path: z.array(z.string().min(1).max(80)).min(1).max(3) }),
  z.object({ type: z.literal("list"), name: z.string().min(1).max(120) }),
  z.object({ type: z.literal("path"), href: z.string().regex(/^\/(cart|quick-order|account\/(lists|company|approvals))?$/) }),
]);
const Run = z.object({
  label: z.string().min(1).max(120),
  persona: z.enum(["guest", ...PERSONA_KEYS]),
  target: Target,
  setup: z
    .object({
      cart: z.array(z.object({ sku: Sku, qty: z.number().int().min(1).max(999) })).max(10).optional(),
      vehicle: z.string().regex(/^[A-Z0-9-]{3,60}\|\d{4}$/).optional(),
    })
    .optional(),
});
const Step = z.object({
  id: z.string().regex(/^S\d{1,2}$/),
  title: z.string().min(1).max(120),
  pillar: z.string().min(1).max(60),
  minutes: z.number().positive().max(5),
  runs: z.array(Run).min(1).max(3),
  talkingPoints: z.array(z.string().min(1).max(400)).length(3),
  expected: z.string().min(1).max(400),
  dmsRef: z.object({ label: z.string(), url: z.url() }).optional(),
  lockRuns: z.boolean().optional(),
});
export const TourSchema = z.object({ version: z.literal(1), steps: z.array(Step).min(1) });

export type Tour = z.infer<typeof TourSchema>;
export type TourStep = Tour["steps"][number];
export type TourRun = TourStep["runs"][number];
export type TourTarget = TourRun["target"];

// Presenters edit data/tour.json by hand. An invalid file must break only the tour, not every page
// (the shop layout renders the tour bar), so fall back to an empty tour and report the problem on /tour.
const parsed = TourSchema.safeParse(raw);
export const tourError: string | null = parsed.success
  ? null
  : parsed.error.issues.slice(0, 5).map((i) => `${i.path.join(".")}: ${i.message}`).join("; ");
if (tourError) console.error(`[tour] data/tour.json is invalid: ${tourError}`);
export const tour: Tour = parsed.success ? parsed.data : { version: 1, steps: [] };
export const TOUR_BUDGET_MINUTES = 15;
export const plannedMinutes = (t: Tour = tour) => t.steps.reduce((n, s) => n + s.minutes, 0);
export const stepById = (id: string | undefined | null) => tour.steps.find((s) => s.id === id) ?? null;
export const nextStep = (id: string) => {
  const i = tour.steps.findIndex((s) => s.id === id);
  return i >= 0 ? (tour.steps[i + 1] ?? null) : null;
};
export const TOUR_COOKIE = "tour_step";
